//! Build script: embeds icons, VERSIONINFO and an application manifest into the executables.
//!
//! The `.res` files are written directly by this script (no `rc.exe` / resource compiler needed)
//! and handed to `link.exe`, whose built-in CVTRES step converts them into the `.rsrc` section:
//!
//! * `predator-service.res` — icon group 1 (normal logo) + VERSIONINFO + manifest
//! * `predator-tray.res` — icon groups 1 (normal) and 2 (service stopped) + VERSIONINFO + manifest
//!
//! The icons come from `assets/*.ico`, generated by `cargo run --example icongen`. Resources are
//! only embedded for `*-windows-msvc` targets. The pure encoding logic lives in [`res`]; it is
//! unit-tested through the `icongen` example's test target (`cargo test --example icongen`), which
//! includes this file as a module.
//!
//! With the `embed-tray` feature (single-file release, `scripts/build.ps1`) it also checks the
//! tray executable named by `PREDATOR_EMBED_TRAY` (which `src/service/setup/embedded.rs`
//! includes) and passes its SHA-256 on as `PREDATOR_EMBED_TRAY_SHA256`, so setup can verify the
//! embedded copy before it installs it.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// Directory of the icon files, relative to the package root.
const ASSETS_DIR: &str = "assets";
/// Icon file for resource group 1 (normal logo; also the icon Explorer shows for both exes).
const ICON_NORMAL: &str = "predator.ico";
/// Icon file for resource group 2 (service-stopped variant; tray only).
const ICON_OFF: &str = "predator-off.ico";

/// One executable that receives resources.
struct BinSpec {
    name: &'static str,
    description: &'static str,
    /// Whether icon group 2 (service stopped) is embedded too.
    with_off_icon: bool,
}

const BINS: [BinSpec; 2] = [
    BinSpec { name: "predator-service", description: "Vigil Service", with_off_icon: false },
    BinSpec { name: "predator-tray", description: "Vigil Tray", with_off_icon: true },
];

const PRODUCT_NAME: &str = "Vigil";
const COMPANY_NAME: &str = "Vigil";
const LEGAL_COPYRIGHT: &str = "Copyright \u{a9} 2026 4fnanK. MIT License.";

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> Result<(), String> {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={ASSETS_DIR}/{ICON_NORMAL}");
    println!("cargo:rerun-if-changed={ASSETS_DIR}/{ICON_OFF}");
    println!("cargo:rerun-if-env-changed={EMBED_TRAY_ENV}");
    if env::var_os("CARGO_FEATURE_EMBED_TRAY").is_some() {
        let (path, hash) = check_embedded_tray(env::var_os(EMBED_TRAY_ENV).map(PathBuf::from))?;
        println!("cargo:rerun-if-changed={}", path.display());
        println!("cargo:rustc-env={EMBED_TRAY_ENV}_SHA256={hash}");
    }

    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    if target_os != "windows" {
        return Ok(());
    }
    if target_env != "msvc" {
        println!(
            "cargo:warning=Windows resources (icons, version info, manifest) are only embedded for \
             MSVC targets; building {target_env} binaries without them."
        );
        return Ok(());
    }

    let manifest_dir = PathBuf::from(env_var("CARGO_MANIFEST_DIR")?);
    let out_dir = PathBuf::from(env_var("OUT_DIR")?);
    let pkg_version = env_var("CARGO_PKG_VERSION")?;
    let numeric = [
        parse_version_part("CARGO_PKG_VERSION_MAJOR")?,
        parse_version_part("CARGO_PKG_VERSION_MINOR")?,
        parse_version_part("CARGO_PKG_VERSION_PATCH")?,
        0,
    ];
    let mut file_flags = 0;
    if env::var("PROFILE").is_ok_and(|p| p == "debug") {
        file_flags |= res::VS_FF_DEBUG;
    }
    if env::var("CARGO_PKG_VERSION_PRE").is_ok_and(|p| !p.is_empty()) {
        file_flags |= res::VS_FF_PRERELEASE;
    }

    let assets = manifest_dir.join(ASSETS_DIR);
    // A missing icon must not block bootstrapping (the icongen example needs this build script to
    // succeed before the icons exist); a corrupt one is a hard error.
    let icons = match (load_icon(&assets.join(ICON_NORMAL))?, load_icon(&assets.join(ICON_OFF))?) {
        (Some(normal), Some(off)) => Some((normal, off)),
        _ => {
            println!(
                "cargo:warning=icons not embedded: {ASSETS_DIR}/{ICON_NORMAL} or {ASSETS_DIR}/{ICON_OFF} is \
                 missing; generate them with `cargo run --example icongen`"
            );
            None
        }
    };

    for bin in &BINS {
        let original_filename = format!("{}.exe", bin.name);
        let info = res::VersionStrings {
            version: numeric,
            file_flags,
            company_name: COMPANY_NAME,
            file_description: bin.description,
            file_version: &pkg_version,
            internal_name: bin.name,
            legal_copyright: LEGAL_COPYRIGHT,
            original_filename: &original_filename,
            product_name: PRODUCT_NAME,
            product_version: &pkg_version,
        };
        let groups: Vec<&[res::IconImage]> = match &icons {
            Some((normal, off)) if bin.with_off_icon => vec![normal.as_slice(), off.as_slice()],
            Some((normal, _)) => vec![normal.as_slice()],
            None => Vec::new(),
        };
        let version = res::version_info(&info)?;
        let data = res::build_res(&groups, &version, res::MANIFEST.as_bytes())
            .map_err(|e| format!("cannot build resources for {}: {e}", bin.name))?;
        let path = out_dir.join(format!("{}.res", bin.name));
        fs::write(&path, &data).map_err(|e| format!("cannot write {}: {e}", path.display()))?;
        println!("cargo:rustc-link-arg-bin={}={}", bin.name, path.display());
    }
    for arg in delay_load_link_args() {
        println!("cargo:rustc-link-arg-bin={SERVICE_BIN}={arg}");
    }
    Ok(())
}

/// The service binary.
const SERVICE_BIN: &str = "predator-service";

/// DLLs that the service imports but only needs on demand, so they are delay-loaded (mapped on
/// the first call instead of at process start). Measured on the idle service: ~0.44 MB commit and
/// ~1.9 MB working set, of which ole32/oleaut32 (they pull in user32, gdi32, gdi32full, imm32 and
/// win32u) are the largest share.
///
/// * `winhttp` — only the proxy fallback of the HTTPS client uses it (`net::http`); the normal
///   path is the direct TcpStream + SChannel transport, so on most PCs it is never loaded (and
///   with it neither its thread pool nor WPAD machinery).
/// * `ole32`, `oleaut32`, `combase`, `api-ms-win-core-winrt-l1-1-0`, `wlanapi` — Wi-Fi SSID lookup
///   (WinRT / NLM / WLAN API); since it runs in the `ssid-helper` child process, the service itself
///   never loads them.
/// * `powrprof` — power capabilities / sleep / hibernate; `version` — Tailscale CLI version;
///   `userenv` — environment block for processes started in a user session; `wtsapi32` — session
///   queries (status screens, lock/logout, session-change events), not used at startup.
/// * `shell32` — only the interactive setup's elevation prompt (`ShellExecuteExW` "runas"); the
///   service never calls it, so shell32 (and what it pulls in) is never mapped into the service.
///
/// All of them are System32 DLLs present on every supported Windows 10/11 installation. A DLL
/// that is not imported at all only produces a linker warning (LNK4199), never an error.
const DELAY_LOAD_DLLS: [&str; 11] = [
    "winhttp.dll",
    "ole32.dll",
    "oleaut32.dll",
    "combase.dll",
    "api-ms-win-core-winrt-l1-1-0.dll",
    "wlanapi.dll",
    "powrprof.dll",
    "version.dll",
    "userenv.dll",
    "wtsapi32.dll",
    "shell32.dll",
];

/// The loader resolves the service's static imports (secur32, crypt32, iphlpapi, wevtapi, bcrypt,
/// ... — not all of them are KnownDLLs) from System32 only (`LOAD_LIBRARY_SEARCH_SYSTEM32`),
/// never from the folder of the executable. The release file is started — and elevated — from
/// wherever it was downloaded, so a DLL planted next to it must not be loaded (Windows 10 1607+).
/// On-demand loads get the same rule at run time (`SetDefaultDllDirectories` in `main_entry`).
const DEPENDENT_LOAD_FLAG: &str = "/DEPENDENTLOADFLAG:0x800";

/// `/DELAYLOAD:<dll>` for every on-demand DLL plus the delay-load helper library, and the
/// System32-only search for the static imports.
fn delay_load_link_args() -> Vec<String> {
    let mut args: Vec<String> = DELAY_LOAD_DLLS.iter().map(|dll| format!("/DELAYLOAD:{dll}")).collect();
    // LNK4199 ("/DELAYLOAD:x ignored; no imports found") is expected for the empty test harness of
    // the binary, which links none of the on-demand code; it is informational only.
    args.push("/IGNORE:4199".into());
    args.push(DEPENDENT_LOAD_FLAG.into());
    args.push("delayimp.lib".into());
    args
}

#[cfg(test)]
mod delay_load_tests {
    use super::*;

    #[test]
    fn delay_load_arguments() {
        let args = delay_load_link_args();
        assert_eq!(args.len(), DELAY_LOAD_DLLS.len() + 3);
        assert!(args.contains(&"/IGNORE:4199".to_string()));
        // Static imports from System32 only (no DLL planting next to the downloaded exe).
        assert!(args.contains(&"/DEPENDENTLOADFLAG:0x800".to_string()));
        assert_eq!(args.last().map(String::as_str), Some("delayimp.lib"));
        for dll in [
            "winhttp.dll",
            "ole32.dll",
            "oleaut32.dll",
            "wlanapi.dll",
            "powrprof.dll",
            "version.dll",
            "userenv.dll",
            "shell32.dll",
        ] {
            assert!(args.contains(&format!("/DELAYLOAD:{dll}")), "{dll} must be delay-loaded");
        }
        // DLLs needed on the idle path (incl. the direct HTTPS transport: ws2_32, secur32/sspicli,
        // crypt32) must stay static imports.
        for dll in [
            "kernel32.dll",
            "advapi32.dll",
            "wevtapi.dll",
            "iphlpapi.dll",
            "ntdll.dll",
            "ws2_32.dll",
            "secur32.dll",
            "crypt32.dll",
        ] {
            assert!(!args.iter().any(|a| a.eq_ignore_ascii_case(&format!("/DELAYLOAD:{dll}"))), "{dll}");
        }
        assert!(args.iter().all(|a| !a.contains(' ')));
    }
}

/// Environment variable with the full path of the `predator-tray.exe` to embed (`embed-tray`).
const EMBED_TRAY_ENV: &str = "PREDATOR_EMBED_TRAY";

/// SHA-256, shared with the program (`src/service/setup/sha256.rs`).
#[allow(dead_code)]
mod sha256 {
    include!("src/service/setup/sha256.rs");
}

/// Validate the tray executable to embed and return its path and SHA-256 (hex).
fn check_embedded_tray(path: Option<PathBuf>) -> Result<(PathBuf, String), String> {
    let path = path.ok_or_else(|| {
        format!(
            "the embed-tray feature needs {EMBED_TRAY_ENV}=<full path of predator-tray.exe>; build the tray first \
             (scripts/build.ps1 does both steps)"
        )
    })?;
    if !path.is_absolute() {
        return Err(format!("{EMBED_TRAY_ENV} must be a full path (got {})", path.display()));
    }
    let bytes = fs::read(&path).map_err(|e| format!("cannot read {EMBED_TRAY_ENV}={}: {e}", path.display()))?;
    if bytes.len() < 1024 || &bytes[..2] != b"MZ" {
        return Err(format!("{EMBED_TRAY_ENV}={} is not a Windows executable", path.display()));
    }
    Ok((path, sha256::hex_digest(&bytes)))
}

#[cfg(test)]
mod embed_tray_tests {
    use super::*;

    #[test]
    fn embedded_tray_checks() {
        assert!(check_embedded_tray(None).unwrap_err().contains(EMBED_TRAY_ENV));
        assert!(check_embedded_tray(Some(PathBuf::from("relative.exe"))).unwrap_err().contains("full path"));
        let dir = env::temp_dir().join(format!("predator-buildrs-{}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        let fake = dir.join("tray.exe");
        fs::write(&fake, b"not an exe").unwrap();
        assert!(check_embedded_tray(Some(fake.clone())).unwrap_err().contains("not a Windows executable"));
        let mut image = b"MZ".to_vec();
        image.resize(4096, 0x90);
        fs::write(&fake, &image).unwrap();
        let (p, hash) = check_embedded_tray(Some(fake.clone())).unwrap();
        assert_eq!(p, fake);
        assert_eq!(hash, sha256::hex_digest(&image));
        assert_eq!(hash.len(), 64);
        fs::remove_dir_all(&dir).ok();
    }
}

fn env_var(name: &str) -> Result<String, String> {
    env::var(name).map_err(|e| format!("environment variable {name} is not available: {e}"))
}

fn parse_version_part(name: &str) -> Result<u16, String> {
    let raw = env_var(name)?;
    raw.parse::<u16>().map_err(|_| format!("{name}={raw} does not fit a Windows version field (0..=65535)"))
}

/// Reads and parses an `.ico` file; `Ok(None)` when it does not exist.
fn load_icon(path: &Path) -> Result<Option<Vec<res::IconImage>>, String> {
    let bytes = match fs::read(path) {
        Ok(bytes) => bytes,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(e) => return Err(format!("cannot read {}: {e}", path.display())),
    };
    let images = res::parse_ico(&bytes)
        .map_err(|e| format!("{}: {e} (regenerate it with `cargo run --example icongen`)", path.display()))?;
    Ok(Some(images))
}

/// Pure `.res` / `.ico` / VERSIONINFO encoding (no I/O), shared with the icongen tests.
pub mod res {
    /// `RT_ICON`: one image of an icon.
    pub const RT_ICON: u16 = 3;
    /// `RT_GROUP_ICON`: icon directory referencing `RT_ICON` images by id.
    pub const RT_GROUP_ICON: u16 = 14;
    /// `RT_VERSION`: VS_VERSIONINFO.
    pub const RT_VERSION: u16 = 16;
    /// `RT_MANIFEST`: side-by-side application manifest.
    pub const RT_MANIFEST: u16 = 24;

    /// Language-neutral resources (icons: found by every `FindResource` language fallback).
    pub const LANG_NEUTRAL: u16 = 0x0000;
    /// English (United States), the language rc.exe / link.exe use for version info + manifest.
    pub const LANG_EN_US: u16 = 0x0409;
    /// Code page of the version strings (UTF-16LE).
    pub const CP_UNICODE: u16 = 1200;

    /// `MOVEABLE | PURE | DISCARDABLE` (rc.exe's flags for icons).
    pub const MEMFLAGS_ICON: u16 = 0x1030;
    /// `MOVEABLE | PURE` (rc.exe's flags for version info and manifests).
    pub const MEMFLAGS_DEFAULT: u16 = 0x0030;

    /// `VS_FIXEDFILEINFO.dwSignature`.
    pub const VS_FFI_SIGNATURE: u32 = 0xFEEF_04BD;
    /// `VS_FIXEDFILEINFO.dwStrucVersion`.
    pub const VS_FFI_STRUCVERSION: u32 = 0x0001_0000;
    /// `VS_FFI_FILEFLAGSMASK`.
    pub const VS_FFI_FILEFLAGSMASK: u32 = 0x3F;
    /// The file contains debugging information.
    pub const VS_FF_DEBUG: u32 = 0x1;
    /// The file is a development / pre-release version.
    pub const VS_FF_PRERELEASE: u32 = 0x2;
    /// `VOS_NT_WINDOWS32`.
    pub const VOS_NT_WINDOWS32: u32 = 0x0004_0004;
    /// `VFT_APP`.
    pub const VFT_APP: u32 = 0x1;

    /// Size of a resource header with ordinal type and name.
    pub const RES_HEADER_LEN: usize = 32;
    /// Size of `VS_FIXEDFILEINFO`.
    pub const FIXED_FILE_INFO_LEN: usize = 52;

    /// Application manifest shared by both executables.
    pub const MANIFEST: &str = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
  <dependency>
    <dependentAssembly>
      <assemblyIdentity type="win32" name="Microsoft.Windows.Common-Controls" version="6.0.0.0" processorArchitecture="*" publicKeyToken="6595b64144ccf1df" language="*"/>
    </dependentAssembly>
  </dependency>
  <trustInfo xmlns="urn:schemas-microsoft-com:asm.v3">
    <security>
      <requestedPrivileges>
        <requestedExecutionLevel level="asInvoker" uiAccess="false"/>
      </requestedPrivileges>
    </security>
  </trustInfo>
  <compatibility xmlns="urn:schemas-microsoft-com:compatibility.v1">
    <application>
      <!-- Windows 10 and Windows 11 -->
      <supportedOS Id="{8e0f7a12-bfb3-4fe8-b9a5-48fd50a15a9a}"/>
    </application>
  </compatibility>
  <application xmlns="urn:schemas-microsoft-com:asm.v3">
    <windowsSettings>
      <dpiAware xmlns="http://schemas.microsoft.com/SMI/2005/WindowsSettings">true/pm</dpiAware>
      <dpiAwareness xmlns="http://schemas.microsoft.com/SMI/2016/WindowsSettings">PerMonitorV2</dpiAwareness>
      <longPathAware xmlns="http://schemas.microsoft.com/SMI/2016/WindowsSettings">true</longPathAware>
    </windowsSettings>
  </application>
</assembly>
"#;

    /// One image of an `.ico` file (raw PNG or DIB bytes plus its directory metadata).
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct IconImage {
        /// Width in pixels; 0 means 256.
        pub width: u8,
        /// Height in pixels; 0 means 256.
        pub height: u8,
        pub color_count: u8,
        pub planes: u16,
        pub bit_count: u16,
        pub data: Vec<u8>,
    }

    const PNG_SIGNATURE: [u8; 8] = [0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A];

    fn u16_at(bytes: &[u8], at: usize) -> Option<u16> {
        bytes.get(at..at + 2).map(|b| u16::from_le_bytes([b[0], b[1]]))
    }

    fn u32_at(bytes: &[u8], at: usize) -> Option<u32> {
        bytes.get(at..at + 4).map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
    }

    /// Parses an `.ico` file (ICONDIR + ICONDIRENTRY[] + image data).
    pub fn parse_ico(bytes: &[u8]) -> Result<Vec<IconImage>, String> {
        let (reserved, kind, count) = match (u16_at(bytes, 0), u16_at(bytes, 2), u16_at(bytes, 4)) {
            (Some(r), Some(k), Some(c)) => (r, k, usize::from(c)),
            _ => return Err("not an .ico file (truncated header)".into()),
        };
        if reserved != 0 || kind != 1 {
            return Err(format!("not an .ico file (reserved={reserved}, type={kind})"));
        }
        if count == 0 {
            return Err("the .ico file contains no images".into());
        }
        let mut images = Vec::with_capacity(count);
        for i in 0..count {
            let entry = 6 + 16 * i;
            let Some(e) = bytes.get(entry..entry + 16) else {
                return Err(format!("directory entry {i} is truncated"));
            };
            let planes = u16::from_le_bytes([e[4], e[5]]);
            let bit_count = u16::from_le_bytes([e[6], e[7]]);
            let size = u32::from_le_bytes([e[8], e[9], e[10], e[11]]) as usize;
            let offset = u32::from_le_bytes([e[12], e[13], e[14], e[15]]) as usize;
            let data = offset
                .checked_add(size)
                .and_then(|end| bytes.get(offset..end))
                .filter(|d| !d.is_empty())
                .ok_or_else(|| format!("image {i} (offset {offset}, {size} bytes) is outside the file"))?;
            let is_png = data.starts_with(&PNG_SIGNATURE);
            let is_dib = u32_at(data, 0) == Some(40);
            if !is_png && !is_dib {
                return Err(format!("image {i} is neither PNG nor a BITMAPINFOHEADER DIB"));
            }
            images.push(IconImage {
                width: e[0],
                height: e[1],
                color_count: e[2],
                // Some writers leave planes/bit count at 0; the group directory needs real values.
                planes: if planes == 0 { 1 } else { planes },
                bit_count: if bit_count == 0 { 32 } else { bit_count },
                data: data.to_vec(),
            });
        }
        Ok(images)
    }

    /// Writer for a 32-bit `.res` file (the format produced by rc.exe and consumed by link.exe).
    #[derive(Debug)]
    pub struct ResFile {
        buf: Vec<u8>,
    }

    impl Default for ResFile {
        /// Starts a `.res` file with the mandatory 32-byte null resource header.
        fn default() -> Self {
            let mut res = ResFile { buf: Vec::new() };
            res.push_header(0, 0, 0, 0, 0);
            res
        }
    }

    impl ResFile {
        fn push_header(&mut self, data_size: u32, type_id: u16, name_id: u16, flags: u16, lang: u16) {
            let b = &mut self.buf;
            b.extend_from_slice(&data_size.to_le_bytes()); // DataSize
            b.extend_from_slice(&(RES_HEADER_LEN as u32).to_le_bytes()); // HeaderSize
            b.extend_from_slice(&[0xFF, 0xFF]); // TYPE: ordinal
            b.extend_from_slice(&type_id.to_le_bytes());
            b.extend_from_slice(&[0xFF, 0xFF]); // NAME: ordinal
            b.extend_from_slice(&name_id.to_le_bytes());
            // Already DWORD aligned (16 bytes so far).
            b.extend_from_slice(&0u32.to_le_bytes()); // DataVersion
            b.extend_from_slice(&flags.to_le_bytes()); // MemoryFlags
            b.extend_from_slice(&lang.to_le_bytes()); // LanguageId
            b.extend_from_slice(&0u32.to_le_bytes()); // Version
            b.extend_from_slice(&0u32.to_le_bytes()); // Characteristics
        }

        /// Appends one resource with ordinal type and name; the data is padded to a DWORD.
        pub fn add(&mut self, type_id: u16, name_id: u16, lang: u16, flags: u16, data: &[u8]) -> Result<(), String> {
            if name_id == 0 {
                return Err(format!("resource of type {type_id} has the invalid id 0"));
            }
            let size = u32::try_from(data.len())
                .map_err(|_| format!("resource {type_id}/{name_id} is too large ({} bytes)", data.len()))?;
            self.push_header(size, type_id, name_id, flags, lang);
            self.buf.extend_from_slice(data);
            pad4(&mut self.buf);
            Ok(())
        }

        /// The finished `.res` file.
        pub fn into_bytes(self) -> Vec<u8> {
            self.buf
        }
    }

    /// `RT_GROUP_ICON` data: GRPICONDIR + one 14-byte GRPICONDIRENTRY per image, whose
    /// `RT_ICON` ids are `first_id`, `first_id + 1`, ...
    pub fn group_icon(images: &[IconImage], first_id: u16) -> Result<Vec<u8>, String> {
        let count = u16::try_from(images.len()).map_err(|_| "too many icon images".to_string())?;
        let mut b = Vec::with_capacity(6 + 14 * images.len());
        b.extend_from_slice(&0u16.to_le_bytes()); // idReserved
        b.extend_from_slice(&1u16.to_le_bytes()); // idType = icon
        b.extend_from_slice(&count.to_le_bytes());
        for (i, img) in images.iter().enumerate() {
            let id = u16::try_from(i)
                .ok()
                .and_then(|i| first_id.checked_add(i))
                .ok_or_else(|| "icon resource ids exhausted".to_string())?;
            let bytes = u32::try_from(img.data.len()).map_err(|_| format!("icon image {i} is too large"))?;
            b.extend_from_slice(&[img.width, img.height, img.color_count, 0]);
            b.extend_from_slice(&img.planes.to_le_bytes());
            b.extend_from_slice(&img.bit_count.to_le_bytes());
            b.extend_from_slice(&bytes.to_le_bytes());
            b.extend_from_slice(&id.to_le_bytes());
        }
        Ok(b)
    }

    /// Values of the VERSIONINFO resource.
    #[derive(Clone, Debug)]
    pub struct VersionStrings<'a> {
        /// Numeric file and product version (major, minor, patch, build).
        pub version: [u16; 4],
        /// `VS_FF_*` flags.
        pub file_flags: u32,
        pub company_name: &'a str,
        pub file_description: &'a str,
        pub file_version: &'a str,
        pub internal_name: &'a str,
        pub legal_copyright: &'a str,
        pub original_filename: &'a str,
        pub product_name: &'a str,
        pub product_version: &'a str,
    }

    /// The value of a VERSIONINFO block.
    enum Value<'a> {
        /// No value (`wValueLength = 0`, text type).
        None,
        /// NUL-terminated UTF-16 text (`wValueLength` counts WORDs including the NUL).
        Text(&'a str),
        /// Binary data (`wValueLength` counts bytes).
        Binary(&'a [u8]),
    }

    fn utf16z(s: &str) -> Vec<u8> {
        s.encode_utf16().chain(std::iter::once(0)).flat_map(u16::to_le_bytes).collect()
    }

    fn pad4(b: &mut Vec<u8>) {
        b.resize(b.len().next_multiple_of(4), 0);
    }

    /// Encodes one VERSIONINFO block: wLength, wValueLength, wType, szKey, padding, value, then
    /// each child DWORD-aligned. `wLength` covers everything except trailing padding.
    fn block(key: &str, value: Value<'_>, children: &[Vec<u8>]) -> Result<Vec<u8>, String> {
        let (value_len, value_type, value_bytes) = match value {
            Value::None => (0, 1u16, Vec::new()),
            Value::Text(s) => {
                let w = utf16z(s);
                (w.len() / 2, 1, w)
            }
            Value::Binary(d) => (d.len(), 0, d.to_vec()),
        };
        let mut b = vec![0u8; 2]; // wLength, patched below
        let value_len = u16::try_from(value_len).map_err(|_| format!("version value of {key} is too long"))?;
        b.extend_from_slice(&value_len.to_le_bytes());
        b.extend_from_slice(&value_type.to_le_bytes());
        b.extend_from_slice(&utf16z(key));
        pad4(&mut b);
        b.extend_from_slice(&value_bytes);
        for child in children {
            pad4(&mut b);
            b.extend_from_slice(child);
        }
        let len = u16::try_from(b.len()).map_err(|_| format!("version block {key} exceeds 64 KiB"))?;
        b[..2].copy_from_slice(&len.to_le_bytes());
        Ok(b)
    }

    /// `VS_FIXEDFILEINFO` for an application.
    pub fn fixed_file_info(version: [u16; 4], file_flags: u32) -> Vec<u8> {
        let ms = (u32::from(version[0]) << 16) | u32::from(version[1]);
        let ls = (u32::from(version[2]) << 16) | u32::from(version[3]);
        let fields = [
            VS_FFI_SIGNATURE,
            VS_FFI_STRUCVERSION,
            ms, // dwFileVersionMS
            ls, // dwFileVersionLS
            ms, // dwProductVersionMS
            ls, // dwProductVersionLS
            VS_FFI_FILEFLAGSMASK,
            file_flags & VS_FFI_FILEFLAGSMASK,
            VOS_NT_WINDOWS32,
            VFT_APP,
            0, // dwFileSubtype
            0, // dwFileDateMS
            0, // dwFileDateLS
        ];
        fields.iter().flat_map(|f| f.to_le_bytes()).collect()
    }

    /// Complete `VS_VERSIONINFO` resource (fixed info + StringFileInfo 040904B0 + VarFileInfo).
    pub fn version_info(v: &VersionStrings<'_>) -> Result<Vec<u8>, String> {
        let strings = [
            ("CompanyName", v.company_name),
            ("FileDescription", v.file_description),
            ("FileVersion", v.file_version),
            ("InternalName", v.internal_name),
            ("LegalCopyright", v.legal_copyright),
            ("OriginalFilename", v.original_filename),
            ("ProductName", v.product_name),
            ("ProductVersion", v.product_version),
        ];
        let mut entries = Vec::with_capacity(strings.len());
        for (key, value) in strings {
            entries.push(block(key, Value::Text(value), &[])?);
        }
        let lang_cp = format!("{LANG_EN_US:04X}{CP_UNICODE:04X}");
        let table = block(&lang_cp, Value::None, &entries)?;
        let string_file_info = block("StringFileInfo", Value::None, &[table])?;
        let translation: Vec<u8> = [LANG_EN_US, CP_UNICODE].iter().flat_map(|w| w.to_le_bytes()).collect();
        let var = block("Translation", Value::Binary(&translation), &[])?;
        let var_file_info = block("VarFileInfo", Value::None, &[var])?;
        let fixed = fixed_file_info(v.version, v.file_flags);
        block("VS_VERSION_INFO", Value::Binary(&fixed), &[string_file_info, var_file_info])
    }

    /// Builds a complete `.res` file: icon group `n` (1-based) gets `RT_GROUP_ICON` id `n`, and the
    /// `RT_ICON` images of all groups get consecutive ids starting at 1; then RT_VERSION 1 and
    /// RT_MANIFEST 1.
    pub fn build_res(icon_groups: &[&[IconImage]], version_info: &[u8], manifest: &[u8]) -> Result<Vec<u8>, String> {
        let mut res = ResFile::default();
        let mut next_icon_id: u16 = 1;
        for (index, images) in icon_groups.iter().enumerate() {
            if images.is_empty() {
                return Err(format!("icon group {} has no images", index + 1));
            }
            let group_id = u16::try_from(index + 1).map_err(|_| "too many icon groups".to_string())?;
            let first_id = next_icon_id;
            for img in images.iter() {
                res.add(RT_ICON, next_icon_id, LANG_NEUTRAL, MEMFLAGS_ICON, &img.data)?;
                next_icon_id = next_icon_id.checked_add(1).ok_or_else(|| "icon resource ids exhausted".to_string())?;
            }
            res.add(RT_GROUP_ICON, group_id, LANG_NEUTRAL, MEMFLAGS_ICON, &group_icon(images, first_id)?)?;
        }
        res.add(RT_VERSION, 1, LANG_EN_US, MEMFLAGS_DEFAULT, version_info)?;
        res.add(RT_MANIFEST, 1, LANG_EN_US, MEMFLAGS_DEFAULT, manifest)?;
        Ok(res.into_bytes())
    }

    /// One resource read back from a `.res` file (test/verification helper).
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ParsedResource {
        pub type_id: u16,
        pub name_id: u16,
        pub lang: u16,
        pub flags: u16,
        pub data: Vec<u8>,
    }

    /// Parses a `.res` file written with ordinal types/names (verification helper). The leading
    /// null resource is checked and skipped.
    pub fn parse_res(bytes: &[u8]) -> Result<Vec<ParsedResource>, String> {
        let null_header = bytes.get(..RES_HEADER_LEN).ok_or("truncated .res file")?;
        if u32_at(null_header, 0) != Some(0) || u32_at(null_header, 4) != Some(RES_HEADER_LEN as u32) {
            return Err("missing 32-byte null resource header".into());
        }
        let mut out = Vec::new();
        let mut pos = RES_HEADER_LEN;
        while pos < bytes.len() {
            let h = bytes.get(pos..pos + RES_HEADER_LEN).ok_or_else(|| format!("truncated header at {pos}"))?;
            let size = u32_at(h, 0).unwrap_or(0) as usize;
            let header_size = u32_at(h, 4).unwrap_or(0) as usize;
            if header_size != RES_HEADER_LEN || u16_at(h, 8) != Some(0xFFFF) || u16_at(h, 12) != Some(0xFFFF) {
                return Err(format!("unsupported resource header at {pos}"));
            }
            let start = pos + header_size;
            let data = bytes.get(start..start + size).ok_or_else(|| format!("truncated data at {start}"))?;
            out.push(ParsedResource {
                type_id: u16_at(h, 10).unwrap_or(0),
                name_id: u16_at(h, 14).unwrap_or(0),
                flags: u16_at(h, 20).unwrap_or(0),
                lang: u16_at(h, 22).unwrap_or(0),
                data: data.to_vec(),
            });
            pos = (start + size).next_multiple_of(4);
        }
        Ok(out)
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        fn png_stub(tag: u8) -> Vec<u8> {
            let mut v = PNG_SIGNATURE.to_vec();
            v.extend_from_slice(&[tag; 5]); // odd length exercises DWORD padding
            v
        }

        fn ico_with(images: &[(u8, Vec<u8>)]) -> Vec<u8> {
            let mut b = vec![0, 0, 1, 0];
            b.extend_from_slice(&(images.len() as u16).to_le_bytes());
            let mut offset = 6 + 16 * images.len();
            for (dim, data) in images {
                b.extend_from_slice(&[*dim, *dim, 0, 0, 1, 0, 32, 0]);
                b.extend_from_slice(&(data.len() as u32).to_le_bytes());
                b.extend_from_slice(&(offset as u32).to_le_bytes());
                offset += data.len();
            }
            for (_, data) in images {
                b.extend_from_slice(data);
            }
            b
        }

        fn sample_strings() -> VersionStrings<'static> {
            VersionStrings {
                version: [1, 2, 3, 0],
                file_flags: VS_FF_PRERELEASE,
                company_name: "Vigil",
                file_description: "Vigil Tray",
                file_version: "1.2.3",
                internal_name: "predator-tray",
                legal_copyright: "Copyright \u{a9} test",
                original_filename: "predator-tray.exe",
                product_name: "Vigil",
                product_version: "1.2.3",
            }
        }

        /// Minimal VERSIONINFO walker: returns (key, value type, value bytes, children) per block.
        fn walk(b: &[u8]) -> (String, u16, Vec<u8>, Vec<Vec<u8>>) {
            let len = u16_at(b, 0).unwrap() as usize;
            let value_len = u16_at(b, 2).unwrap() as usize;
            let value_type = u16_at(b, 4).unwrap();
            assert!(len <= b.len(), "wLength {len} beyond buffer {}", b.len());
            let mut key = Vec::new();
            let mut pos = 6;
            loop {
                let c = u16_at(b, pos).unwrap();
                pos += 2;
                if c == 0 {
                    break;
                }
                key.push(c);
            }
            let key = String::from_utf16(&key).unwrap();
            pos = pos.next_multiple_of(4);
            let value_bytes = if value_type == 1 { value_len * 2 } else { value_len };
            let value = b[pos..pos + value_bytes].to_vec();
            pos += value_bytes;
            let mut children = Vec::new();
            loop {
                pos = pos.next_multiple_of(4);
                if pos >= len {
                    break;
                }
                let child_len = u16_at(b, pos).unwrap() as usize;
                assert!(child_len > 0 && pos + child_len <= len, "child overruns parent {key}");
                children.push(b[pos..pos + child_len].to_vec());
                pos += child_len;
            }
            (key, value_type, value, children)
        }

        #[test]
        fn parse_ico_reads_entries() {
            let ico = ico_with(&[(16, png_stub(1)), (0, png_stub(2))]);
            let images = parse_ico(&ico).unwrap();
            assert_eq!(images.len(), 2);
            assert_eq!(images[0].width, 16);
            assert_eq!(images[1].width, 0);
            assert_eq!(images[1].data, png_stub(2));
            assert_eq!((images[0].planes, images[0].bit_count), (1, 32));
        }

        #[test]
        fn parse_ico_rejects_bad_input() {
            assert!(parse_ico(&[]).is_err());
            assert!(parse_ico(&[0, 0, 2, 0, 1, 0]).is_err()); // cursor type
            assert!(parse_ico(&[0, 0, 1, 0, 0, 0]).is_err()); // no images
            let mut ico = ico_with(&[(16, png_stub(1))]);
            ico.truncate(ico.len() - 3);
            assert!(parse_ico(&ico).is_err()); // data outside file
            let bogus = ico_with(&[(16, vec![1, 2, 3, 4, 5])]);
            assert!(parse_ico(&bogus).is_err()); // neither PNG nor DIB
        }

        #[test]
        fn res_file_layout() {
            let mut res = ResFile::default();
            res.add(RT_MANIFEST, 1, LANG_EN_US, MEMFLAGS_DEFAULT, b"abcde").unwrap();
            let bytes = res.into_bytes();
            // null header
            assert_eq!(&bytes[..16], &[0, 0, 0, 0, 32, 0, 0, 0, 0xFF, 0xFF, 0, 0, 0xFF, 0xFF, 0, 0]);
            assert!(bytes[16..32].iter().all(|&b| b == 0));
            // resource header
            assert_eq!(u32_at(&bytes, 32), Some(5));
            assert_eq!(u32_at(&bytes, 36), Some(32));
            assert_eq!(&bytes[40..48], &[0xFF, 0xFF, 24, 0, 0xFF, 0xFF, 1, 0]);
            assert_eq!(u32_at(&bytes, 48), Some(0)); // DataVersion
            assert_eq!(u16_at(&bytes, 52), Some(MEMFLAGS_DEFAULT));
            assert_eq!(u16_at(&bytes, 54), Some(LANG_EN_US));
            assert_eq!(&bytes[64..69], b"abcde");
            assert_eq!(bytes.len(), 72); // padded to a DWORD
            assert!(ResFile::default().add(RT_ICON, 0, 0, 0, b"x").is_err());
        }

        #[test]
        fn group_icon_layout() {
            let images = parse_ico(&ico_with(&[(16, png_stub(1)), (0, png_stub(2))])).unwrap();
            let g = group_icon(&images, 10).unwrap();
            assert_eq!(g.len(), 6 + 2 * 14);
            assert_eq!(&g[..6], &[0, 0, 1, 0, 2, 0]);
            assert_eq!(&g[6..10], &[16, 16, 0, 0]);
            assert_eq!(u16_at(&g, 10), Some(1)); // planes
            assert_eq!(u16_at(&g, 12), Some(32)); // bit count
            assert_eq!(u32_at(&g, 14), Some(13)); // bytes in res
            assert_eq!(u16_at(&g, 18), Some(10)); // id
            assert_eq!(&g[20..22], &[0, 0]); // 256 px
            assert_eq!(u16_at(&g, 32), Some(11));
        }

        #[test]
        fn version_info_structure() {
            let vi = version_info(&sample_strings()).unwrap();
            assert_eq!(vi.len() % 4, 0);
            assert_eq!(u16_at(&vi, 0).map(usize::from), Some(vi.len()));
            assert_eq!(u16_at(&vi, 2).map(usize::from), Some(FIXED_FILE_INFO_LEN));
            assert_eq!(u32_at(&vi, 40), Some(VS_FFI_SIGNATURE)); // classic offset of the fixed info
            assert_eq!(u32_at(&vi, 48), Some(0x0001_0002)); // file version MS
            assert_eq!(u32_at(&vi, 52), Some(0x0003_0000)); // file version LS
            assert_eq!(u32_at(&vi, 64), Some(VS_FFI_FILEFLAGSMASK));
            assert_eq!(u32_at(&vi, 68), Some(VS_FF_PRERELEASE));
            assert_eq!(u32_at(&vi, 72), Some(VOS_NT_WINDOWS32));
            assert_eq!(u32_at(&vi, 76), Some(VFT_APP));

            let (key, ty, fixed, children) = walk(&vi);
            assert_eq!((key.as_str(), ty, fixed.len()), ("VS_VERSION_INFO", 0, FIXED_FILE_INFO_LEN));
            assert_eq!(children.len(), 2);
            let (sfi, sfi_ty, _, tables) = walk(&children[0]);
            assert_eq!((sfi.as_str(), sfi_ty, tables.len()), ("StringFileInfo", 1, 1));
            let (table, _, _, strings) = walk(&tables[0]);
            assert_eq!(table, "040904B0");
            let mut found = Vec::new();
            for s in &strings {
                let (k, t, v, c) = walk(s);
                assert_eq!(t, 1);
                assert!(c.is_empty());
                let units: Vec<u16> = (0..v.len() / 2).map(|i| u16::from_le_bytes([v[2 * i], v[2 * i + 1]])).collect();
                assert_eq!(units.last(), Some(&0), "value of {k} must be NUL terminated");
                found.push((k, String::from_utf16(&units[..units.len() - 1]).unwrap()));
            }
            let get = |k: &str| found.iter().find(|(key, _)| key == k).map(|(_, v)| v.clone());
            assert_eq!(found.len(), 8);
            assert_eq!(get("FileDescription").as_deref(), Some("Vigil Tray"));
            assert_eq!(get("OriginalFilename").as_deref(), Some("predator-tray.exe"));
            assert_eq!(get("LegalCopyright").as_deref(), Some("Copyright \u{a9} test"));
            assert_eq!(get("ProductVersion").as_deref(), Some("1.2.3"));
            let (vfi, _, _, vars) = walk(&children[1]);
            assert_eq!(vfi, "VarFileInfo");
            let (var, var_ty, translation, _) = walk(&vars[0]);
            assert_eq!((var.as_str(), var_ty), ("Translation", 0));
            assert_eq!(translation, vec![0x09, 0x04, 0xB0, 0x04]);
        }

        #[test]
        fn build_res_assigns_unique_ids() {
            let normal = parse_ico(&ico_with(&[(16, png_stub(1)), (32, png_stub(2)), (0, png_stub(3))])).unwrap();
            let off = parse_ico(&ico_with(&[(16, png_stub(4)), (32, png_stub(5))])).unwrap();
            let vi = version_info(&sample_strings()).unwrap();
            let bytes = build_res(&[&normal, &off], &vi, MANIFEST.as_bytes()).unwrap();
            let parsed = parse_res(&bytes).unwrap();
            let icons: Vec<_> = parsed.iter().filter(|r| r.type_id == RT_ICON).collect();
            assert_eq!(icons.iter().map(|r| r.name_id).collect::<Vec<_>>(), vec![1, 2, 3, 4, 5]);
            assert_eq!(icons[3].data, png_stub(4));
            let groups: Vec<_> = parsed.iter().filter(|r| r.type_id == RT_GROUP_ICON).collect();
            assert_eq!(groups.len(), 2);
            assert_eq!((groups[0].name_id, groups[1].name_id), (1, 2));
            assert_eq!(u16_at(&groups[1].data, 4), Some(2));
            assert_eq!(u16_at(&groups[1].data, 6 + 12), Some(4)); // first image of group 2 → id 4
            let version = parsed.iter().find(|r| r.type_id == RT_VERSION).unwrap();
            assert_eq!((version.name_id, version.lang, &version.data), (1, LANG_EN_US, &vi));
            let manifest = parsed.iter().find(|r| r.type_id == RT_MANIFEST).unwrap();
            assert_eq!(manifest.data, MANIFEST.as_bytes());
            assert!(build_res(&[&[]], &vi, b"m").is_err());
        }

        #[test]
        fn manifest_contains_required_settings() {
            for needle in [
                "level=\"asInvoker\"",
                ">PerMonitorV2<",
                ">true/pm<",
                "{8e0f7a12-bfb3-4fe8-b9a5-48fd50a15a9a}",
                "Microsoft.Windows.Common-Controls",
                "version=\"6.0.0.0\"",
                "<longPathAware",
            ] {
                assert!(MANIFEST.contains(needle), "manifest lacks {needle}");
            }
            assert!(MANIFEST.is_ascii());
        }
    }
}
